state.settings.transactions=state.settings.transactions||{purchasePrefix:"GRN-",outwardPrefix:"OUT-",adjustmentPrefix:"ADJ-",autoNumber:true,manualNumber:false,edit:true,delete:true,backdatedPurchase:true,backdatedOutward:true,openLastPurchase:true,openLastOutward:true,mode:"Keyboard first"};
