function baseSettingsScreen(){const s=state.settings,g=s.general,i=s.inventory,t=s.transactions;const toggle=(path,label,desc)=>`<label class="setting-toggle"><span><b>${label}</b><small>${desc}</small></span><input type="checkbox" ${path.split(".").reduce((o,k)=>o[k],s)?"checked":""} onchange="setField('${path}',this.checked);save()"><i></i></label>`;const nav=["General","Inventory","Transactions","Number & Rounding","Users & Permissions","Security","Backup & Data","Appearance","Keyboard Shortcuts","System Information"];return layout("Settings","Inventory control center for StockSense.",`<button class="secondary" onclick="resetSettings()">Reset defaults</button><button class="primary" onclick="save();toast('Settings saved')">Save changes</button>`,`<div class="settings-layout"><aside class="settings-nav">${nav.map((x,n)=>`<button class="${n===0?"active":""}" onclick="document.getElementById('setting-${n}').scrollIntoView({behavior:'smooth'})">${x}</button>`).join("")}</aside><div class="settings-content"><section id="setting-0" class="settings-section"><h2>General</h2><p>Business identity and default transaction context.</p><div class="settings-grid">${field("settings.general.company","Business / company name",g.company)}${field("settings.general.address","Address",g.address)}${field("settings.general.phone","Phone number",g.phone)}${field("settings.general.email","Email",g.email)}${selectField("settings.general.financialYear","Financial year starts",g.financialYear,["January","April","July"])}${selectField("settings.general.department","Default department",g.department,departments)}${selectField("settings.general.location","Default warehouse / location",g.location,state.stores.map(x=>x[0]))}${selectField("settings.general.dateFormat","Date format",g.dateFormat,["DD-MM-YYYY","YYYY-MM-DD","MM-DD-YYYY"])}</div>${toggle("general.confirmDelete","Confirm before deleting","Protect posted transactions from accidental deletion.")}</section><section id="setting-1" class="settings-section"><h2>Inventory</h2><p>Controls that directly affect stock validation and balances.</p><div class="settings-grid">${selectField("inventory.valuation","Stock valuation method",i.valuation,["Weighted average","FIFO"])}${selectField("inventory.unit","Default unit",i.unit,["kg","L","piece","case"])}${numberField("inventory.lowThreshold","Low-stock warning threshold",i.lowThreshold)}</div>${toggle("inventory.negative","Enable negative stock","Allow issues beyond available stock.")}${toggle("inventory.adjustment","Allow stock adjustment","Enable adjustment vouchers.")}${toggle("inventory.backdated","Allow backdated transactions","Permit historical purchase and outward dates.")}${toggle("inventory.recalculate","Automatic stock recalculation","Rebuild balances after historical edits.")}${toggle("inventory.departmentTracking","Department-wise stock tracking","Keep department on outward movements.")}${toggle("inventory.multiLocation","Multi-location stock tracking","Track store/location on every movement.")}</section><section id="setting-2" class="settings-section"><h2>Transactions</h2><p>Numbering, edit permissions and voucher entry behavior.</p><div class="settings-grid">${field("settings.transactions.purchasePrefix","Purchase numbering format",t.purchasePrefix)}${field("settings.transactions.outwardPrefix","Outward numbering format",t.outwardPrefix)}${field("settings.transactions.adjustmentPrefix","Adjustment numbering format",t.adjustmentPrefix)}${selectField("settings.transactions.mode","Default transaction screen mode",t.mode,["Keyboard first","Comfortable"])}</div>${toggle("transactions.autoNumber","Automatic transaction numbering","Generate sequential references.")}${toggle("transactions.edit","Allow editing saved transactions","Owner/Admin can update posted vouchers.")}${toggle("transactions.delete","Allow deleting/cancelling transactions","Require confirmation before cancellation.")}${toggle("transactions.backdatedPurchase","Allow backdated Purchase","Purchase dates may be earlier than today.")}${toggle("transactions.backdatedOutward","Allow backdated Outward","Outward dates may be earlier than today.")}${toggle("transactions.openLastPurchase","Automatically open last Purchase","Resume the latest purchase when opening the module.")}${toggle("transactions.openLastOutward","Automatically open last Outward","Resume the latest outward when opening the module.")}</section><section id="setting-3" class="settings-section"><h2>Number & Rounding</h2><p>Display precision only; stored values remain unrounded.</p><div class="settings-grid">${selectField("settings.decimals","Default decimal places",String(state.settings.decimals),["0","1","2","3","4","5"])}${selectField("settings.rounding","Rounding method",state.settings.rounding,["none","normal","up","down"])}</div><div class="setting-note">Applied immediately to quantities, rates, totals, stock balances and reports.</div></section><section id="setting-4" class="settings-section"><h2>Users & Permissions</h2><p>Owner/Admin retains full control over the inventory system.</p>${["View Dashboard","View Stock","Create Purchase","Edit Purchase","Delete Purchase","Create Outward","Edit Outward","Delete Outward","Create Stock Adjustment","Edit Backdated Transactions","Delete Transactions","View Reports","Export Data","Manage Items","Manage Departments","Manage Users","Change Settings","Backup / Restore Data"].map(x=>`<label class="permission-row"><span>${x}</span><input type="checkbox" checked ${x==="Change Settings"?"disabled":""}></label>`).join("")}</section><section id="setting-5" class="settings-section"><h2>Security</h2><p>Protect sensitive transaction and configuration changes.</p>${toggle("general.confirmDelete","Require confirmation for destructive actions","Confirm cancellation and deletion actions.")}<div class="settings-grid">${selectField("settings.securityLock","Auto-lock after inactivity",state.settings.securityLock||"Never",["Never","5 minutes","15 minutes","30 minutes"])}${selectField("settings.startupLock","Lock application on startup",state.settings.startupLock||"No",["No","Yes"])}</div><div class="setting-note">Activity and transaction changes are retained in the Activity Log.</div></section><section id="setting-6" class="settings-section"><h2>Backup & Data</h2><p>Export or preserve the local StockSense data store.</p><div class="settings-actions"><button class="secondary" onclick="backupData()">Manual backup</button><button class="secondary" onclick="exportData()">Export data</button><button class="secondary" onclick="toast('Restore requires selecting a StockSense backup file')">Restore backup</button></div><div class="setting-note">Last backup: ${state.lastBackup||"Not yet created"} · Data location: browser storage</div></section><section id="setting-7" class="settings-section"><h2>Appearance</h2><p>Keep the workspace comfortable for long inventory sessions.</p><div class="settings-grid">${selectField("settings.theme","Theme",state.settings.theme||"System",["Light","Dark","System"])}${selectField("settings.density","Table density",state.settings.density||"Comfortable",["Compact","Comfortable"])}${selectField("settings.fontSize","Default font size",state.settings.fontSize||"14px",["13px","14px","15px"])}</div></section><section id="setting-8" class="settings-section"><h2>Keyboard Shortcuts</h2><p>Voucher entry remains optimized for minimal mouse use.</p><div class="shortcut-reference">${["New Purchase - Ctrl + N","New Outward - Ctrl + Shift + N","Save - Ctrl + S","Edit - F2","Delete - Ctrl + D","Cancel - Esc","Search - Alt + S","Next Field - Enter / Tab","Previous Field - Shift + Tab","Open Stock - Alt + I","Open Reports - Alt + R","Go Back - Esc"].map(x=>`<span>${x}</span>`).join("")}</div></section><section id="setting-9" class="settings-section"><h2>System Information</h2><p>Current application and data status.</p><div class="system-facts"><b>StockSense version <span>1.0.0</span></b><b>Database status <span>Local data available</span></b><b>Current financial year <span>${g.financialYear} start</span></b><b>Transactions <span>${state.transactions.length}</span></b><b>Products <span>${state.products.length}</span></b><b>Last backup <span>${state.lastBackup||"Not yet created"}</span></b></div></section></div></div>`)}
function settingsScreen(){const html=baseSettingsScreen();return html.replace("</section><section id=\"setting-1\"",`<div class="settings-section settings-store-link"><h2>Stores & locations</h2><p>Create, rename, assign managers, or delete inventory locations.</p><button class="primary" onclick="showView('stores')">Manage stores & locations →</button></div></section><section id="setting-1"`)}
function field(path,label,value){return `<label class="setting-field">${label}<input value="${value||""}" onchange="setField('${path}',this.value);save()"></label>`}
function numberField(path,label,value){return `<label class="setting-field">${label}<input type="number" value="${value}" onchange="setField('${path}',Number(this.value));save()"></label>`}
function selectField(path,label,value,options){return `<label class="setting-field">${label}<select onchange="setField('${path}',this.value);save()">${options.map(x=>`<option ${String(x)===String(value)?"selected":""}>${x}</option>`).join("")}</select></label>`}
function resetSettings(){if(confirm("Restore StockSense settings to defaults?")){state.settings={...state.settings,decimals:2,rounding:"normal",general:{...state.settings.general,confirmDelete:true},inventory:{...state.settings.inventory,negative:false,backdated:true,recalculate:true},transactions:{...state.settings.transactions,autoNumber:true,edit:true,delete:true}};save();showView("settings");toast("Defaults restored")}}
function backupData(){state.lastBackup=new Date().toLocaleString();save();const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="stocksense-backup.json";a.click();toast("Backup downloaded")}
function exportData(){backupData()}
function reports(){const tx=state.transactions,types=["All","Purchase","Stock Outward","Transfer in","Transfer out","Adjustment","Wastage","Consumption"];return layout("Reports","Fast, ledger-backed inventory reporting with live filters.",`<button class="secondary" onclick="exportReportCsv()">Export CSV</button><button class="secondary" onclick="window.print()">Print</button>`,`<div class="report-dashboard"><div class="report-categories"><h3>Report centre</h3>${["Stock","Purchases","Outward","Analysis","Audit"].map((g,i)=>`<div class="report-group"><b>${g}</b>${(i===0?["Current Stock","Stock Ledger","Low Stock"]:i===1?["Purchase Register","Purchase Analysis"]:i===2?["Outward Register","Outward Analysis"]:i===3?["Department Summary","Item Movement","Purchase vs Outward"]:["Transaction History","User Activity","Backdated Transactions"]).map(x=>`<button onclick="selectReport('${x}')">${x}<span>›</span></button>`).join("")}</div>`).join("")}</div><div class="report-main"><div class="report-filters"><label>Date range<select id="report-range" onchange="renderReportRows()"><option>All Time</option><option>Today</option><option>Yesterday</option><option selected>This Month</option><option>Previous Month</option><option>Current Financial Year</option></select></label><label>Type<select id="report-type" onchange="renderReportRows()">${types.map(x=>`<option>${x}</option>`).join("")}</select></label><label>Department<select id="report-department" onchange="renderReportRows()"><option>All Departments</option>${departments.map(x=>`<option>${x}</option>`).join("")}</select></label><label>Search<input id="report-search" placeholder="Item, reference or user" oninput="renderReportRows()"></label></div><div id="report-results">${reportResults(tx)}</div></div></div>`)}
function reportResults(rows){const purchases=rows.filter(t=>t.type==="Purchase").reduce((a,t)=>a+Math.abs(t.qty)*t.cost,0),outward=rows.filter(t=>t.type==="Stock Outward").reduce((a,t)=>a+Math.abs(t.qty)*t.cost,0),qty=rows.reduce((a,t)=>a+Math.abs(t.qty),0);return `<div class="metrics">${metric("Transactions",rows.length,"⌁","blue","Filtered ledger")} ${metric("Total quantity",numberValue(qty),"▣","green","Inward and outward")} ${metric("Purchase value",numberValue(purchases),"↗","green","Filtered purchases")} ${metric("Outward value",numberValue(outward),"↘","amber","Filtered issues")}</div><div class="panel view-table"><div class="panel-head"><span class="panel-title">Transaction history</span><span class="pill">${rows.length} rows</span></div><table class="table"><thead><tr><th>Date</th><th>Entry no.</th><th>Type</th><th>Item</th><th>Department</th><th>Quantity</th><th>Rate</th><th>Amount</th><th>User</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${fmtDate(t.date)}</td><td><b>${t.ref}</b></td><td><span class="tag">${t.type}</span></td><td>${t.product}</td><td>${t.department||"—"}</td><td>${numberValue(Math.abs(t.qty))}</td><td>${numberValue(t.cost)}</td><td>${numberValue(Math.abs(t.qty)*t.cost)}</td><td>${t.user}</td></tr>`).join("")||'<tr><td colspan="9" class="empty-state">No transactions match these filters.</td></tr>'}</tbody></table></div>`}
function renderReportRows(){const q=(document.getElementById("report-search")?.value||"").toLowerCase(),type=document.getElementById("report-type")?.value||"All",dept=document.getElementById("report-department")?.value||"All Departments",range=document.getElementById("report-range")?.value||"All Time",now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),1);const rows=state.transactions.filter(t=>{const d=new Date(t.date);let inRange=true;if(range==="Today")inRange=d.toDateString()===now.toDateString();if(range==="This Month")inRange=d>=start;if(range==="Previous Month")inRange=d>=new Date(now.getFullYear(),now.getMonth()-1,1)&&d<start;if(range==="Yesterday"){const y=new Date(now);y.setDate(y.getDate()-1);inRange=d.toDateString()===y.toDateString()}return inRange&&(type==="All"||t.type===type)&&(dept==="All Departments"||t.department===dept)&&`${t.product} ${t.ref} ${t.user}`.toLowerCase().includes(q)});document.getElementById("report-results").innerHTML=reportResults(rows)}
function exportReportCsv(){const rows=state.transactions.map(t=>[t.date,t.ref,t.type,t.product,t.department||"",Math.abs(t.qty),t.cost,Math.abs(t.qty)*t.cost,t.user]);const csv=[["Date","Entry No","Type","Item","Department","Quantity","Rate","Amount","User"],...rows].map(r=>r.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="stocksense-report.csv";a.click();toast("Report exported")}
function selectReport(name){toast(`${name} report selected`);if(name==="Current Stock"){showView("inventory")}else if(name==="Stock Ledger"||name==="Transaction History"){showView("inventory-ledger")}else if(name==="Purchase Register"){showView("purchasing")}else if(name==="Outward Register"){showView("outward")}}
let outwardDraft={department:"Kitchen",store:"Downtown Kitchen",date:today,issuedTo:"",reference:"",remarks:"",items:[],isNew:false};
const departments=["Kitchen","Bar","Bakery","Housekeeping","Maintenance","Production","Office","Other"];
const nextOutwardNo=()=>`OUT-${String(state.outwards.length+1).padStart(5,"0")}`;
function newOutward(){outwardDraft={department:"Kitchen",store:"Downtown Kitchen",date:today,issuedTo:"",reference:"",remarks:"",items:[],isNew:true};showView("outward");setTimeout(addOutwardRow,0)}
function loadOutward(no){const v=state.outwards.find(x=>x.no===no);if(v){outwardDraft={...v,items:v.items.map(i=>({...i}))};showView("outward")}}
function outwardRows(){return outwardDraft.items.length?outwardDraft.items.map((item,i)=>{const p=productByName(item.product),available=p?.stock||0,rate=item.rate||p?.cost||0,amount=(item.qty||0)*rate;return `<tr><td>${i+1}</td><td><input class="out-item" data-index="${i}" list="out-product-list" value="${item.product||""}" placeholder="Search item name / brand" oninput="setOutwardProduct(${i},this.value)" onkeydown="outwardKey(event,${i},'product')"></td><td>${p?.brand||"—"}</td><td><span class="available ${item.qty>available?"invalid":""}">${numberValue(available)} ${p?.unit||""}</span></td><td><input class="out-qty" data-index="${i}" type="number" min="0" step="0.01" value="${item.qty||""}" oninput="setOutwardQty(${i},this.value)" onkeydown="outwardKey(event,${i},'qty')" placeholder="0.00"></td><td>${p?.unit||"—"}</td><td><input type="number" min="0" step="0.01" value="${rate}" oninput="outwardDraft.items[${i}].rate=Number(this.value)||0;showView('outward')"></td><td><b>${numberValue(amount)}</b></td><td><select><option>Default batch</option></select></td><td><input value="${item.remarks||""}" oninput="outwardDraft.items[${i}].remarks=this.value" placeholder="Optional"></td><td><button class="row-delete" onclick="removeOutwardRow(${i})">×</button></td></tr>`}).join(""):`<tr><td colspan="11" class="empty-state">Press <b>F5</b> or <b>Ctrl+A</b> to add the first item.</td></tr>`}
function outwardTotal(){return outwardDraft.items.reduce((a,item)=>{const p=productByName(item.product),rate=Number(item.rate)||Number(p?.cost)||0;return a+(Number(item.qty)||0)*rate},0)}
function outwardScreen(){const qty=outwardDraft.items.reduce((a,i)=>a+(Number(i.qty)||0),0),invalid=outwardDraft.items.some(i=>{const p=productByName(i.product);return !p||!i.qty||i.qty>p.stock});return layout("Stock outward","Department-wise multi-item issue voucher with live stock validation.",`<button class="secondary" onclick="newOutward()">＋ New outward</button>${outwardDraft.no?'<button class="secondary" onclick="deleteOutward()">Cancel transaction</button>':""}<button class="secondary" onclick="cancelOutward()">Esc Cancel</button><button class="secondary" onclick="printOutward()">F9 Print</button><button class="primary" onclick="saveOutward()" ${invalid||!outwardDraft.department?"disabled":""}>F8 Save outward</button>`,`<div class="tally-command-bar"><b>Stock outward voucher</b><span>P: Print</span><span>E: Export</span><span>K: Keyboard</span><span>Ctrl + M: Change mode</span></div><div class="shortcut-strip"><b>Keyboard flow</b><span>F2 Date</span><span>F3 Department</span><span>F4 Store</span><span>F5 Add item</span><span>F6 Quantity</span><span>F7 Remove</span><span>F8 Save</span><span>Alt+S Search</span><span>Enter Next</span></div><div class="entry-hotkeys"><b>Voucher actions</b><span>F2 · Date</span><span>F3 · Department</span><span>F5 · Add item</span><span>F8 · Save</span><span>F9 · Print</span><span>Esc · Cancel</span></div><div class="voucher-head panel"><div class="voucher-title"><span class="voucher-number">${nextOutwardNo()}</span><span class="status expiry">${outwardDraft.no?"SAVED":"DRAFT"}</span></div><div class="voucher-fields"><label>Outward date<input id="out-date" type="date" value="${outwardDraft.date}" onchange="outwardDraft.date=this.value"></label><label>Department<select id="out-department" onchange="outwardDraft.department=this.value">${departments.map(d=>`<option ${d===outwardDraft.department?"selected":""}>${d}</option>`).join("")}</select></label><label>Store / location<select id="out-store" onchange="outwardDraft.store=this.value">${state.stores.map(s=>`<option ${s[0]===outwardDraft.store?"selected":""}>${s[0]}</option>`).join("")}</select></label><label>Issued to<input id="out-issued" value="${outwardDraft.issuedTo}" oninput="outwardDraft.issuedTo=this.value" placeholder="Person / team"></label><label>Reference no.<input id="out-reference" value="${outwardDraft.reference}" oninput="outwardDraft.reference=this.value" placeholder="Optional reference"></label><label>Narration / remarks<input id="out-remarks" value="${outwardDraft.remarks}" oninput="outwardDraft.remarks=this.value" placeholder="Reason for issue"></label></div></div><div class="panel outward-grid"><div class="panel-head"><span class="panel-title">Items to issue</span><div><span class="pill">${outwardDraft.items.length} lines</span><button class="panel-link" onclick="addOutwardRow()">＋ Add row</button></div></div><datalist id="out-product-list">${state.products.map(p=>`<option value="${p.name}">${p.brand||""} · ${p.category||""}</option>`).join("")}</datalist><div class="outward-table-wrap"><table class="table outward-table"><thead><tr><th>S.No</th><th>Item name</th><th>Brand</th><th>Available</th><th>Qty</th><th>Unit</th><th>Rate</th><th>Amount</th><th>Batch</th><th>Remarks</th><th></th></tr></thead><tbody>${outwardRows()}</tbody></table></div></div><div class="outward-footer"><div class="validation-note ${invalid?"has-error":"valid"}">${invalid?"⚠ Check item selection and available stock":"✓ All quantities validated against live stock"}</div><div class="total-box"><span>Total quantity <b>${numberValue(qty)}</b></span><strong>Total value ${numberValue(outwardTotal())}</strong></div></div><div class="panel register-panel"><div class="panel-head"><span class="panel-title">Outward register</span><span class="pill">${state.outwards.length} saved vouchers</span></div>${outwardRegister()}</div>`) }
function outwardRegister(){return `<table class="table"><thead><tr><th>Outward no.</th><th>Date</th><th>Department</th><th>Store</th><th>Items</th><th>Total qty</th><th>Total value</th><th>User</th><th>Status</th><th>PDF</th></tr></thead><tbody>${state.outwards.map(v=>`<tr class="clickable-row" onclick="loadOutward('${v.no}')"><td><b>${v.no}</b></td><td>${fmtDate(v.date)}</td><td>${v.department}</td><td>${v.store}</td><td>${v.items.length}</td><td>${numberValue(v.items.reduce((a,i)=>a+i.qty,0))}</td><td>${numberValue(v.total)}</td><td>${v.user}</td><td><span class="status ok">Posted</span></td><td><button class="secondary" onclick="event.stopPropagation();printOutward('${v.no}')">PDF</button></td></tr>`).join("")||'<tr><td colspan="10" class="empty-state">No outward vouchers posted yet.</td></tr>'}</tbody></table>`}
function addOutwardRow(){outwardDraft.items.push({product:"",qty:0,remarks:""});showView("outward");setTimeout(()=>document.querySelector(".out-item:last-of-type")?.focus(),0)}
function removeOutwardRow(i){outwardDraft.items.splice(i,1);showView("outward")}
function setOutwardProduct(i,value){let p=productByName(value)||state.products.find(x=>x.sku===value||x.barcode===value);if(p)outwardDraft.items[i].product=p.name;showView("outward");const el=document.querySelector(`.out-item[data-index="${i}"]`);if(el){el.value=value;el.focus();el.setSelectionRange(value.length,value.length)}}
function setOutwardQty(i,value){outwardDraft.items[i].qty=Number(value)||0;showView("outward")}
function outwardKey(e,i,field){if(e.key==="Enter"){e.preventDefault();if(field==="product")document.querySelector(`.out-qty[data-index="${i}"]`)?.focus();else if(i===outwardDraft.items.length-1)addOutwardRow();else document.querySelector(`.out-item[data-index="${i+1}"]`)?.focus()}}
function saveOutward(){const invalid=outwardDraft.items.length===0||outwardDraft.items.some(i=>{const p=productByName(i.product);return !p||!i.qty||i.qty>p.stock});if(invalid||!outwardDraft.department){toast("Complete the voucher and resolve stock errors");return}const no=outwardDraft.no||nextOutwardNo();if(!confirm(`${outwardDraft.no?"Update":"Post"} ${no} and recalculate stock?`))return;const prior=state.outwards.find(v=>v.no===no);if(prior){state.transactions=state.transactions.filter(t=>t.ref!==no);state.outwards=state.outwards.filter(v=>v.no!==no)}const now=new Date().toISOString(),items=outwardDraft.items.map(i=>{const p=productByName(i.product);return {...i,unit:p.unit,rate:i.rate||p.cost,amount:i.qty*(i.rate||p.cost),batch:i.batch||"Default batch"} });items.forEach(i=>state.transactions.push({id:"TX-"+Date.now()+i.product,date:outwardDraft.date+"T12:00:00",type:"Stock Outward",product:i.product,department:outwardDraft.department,store:outwardDraft.store,qty:-i.qty,unit:i.unit,cost:i.rate,value:i.amount,user:state.currentUser,ref:no,reference:outwardDraft.reference}));state.outwards.unshift({...outwardDraft,no,items,total:items.reduce((a,i)=>a+i.amount,0),user:state.currentUser,status:"Posted",date:outwardDraft.date,createdAt:now});rebuildStock();toast(`${no} ${prior?"updated":"posted"} — stock recalculated`);outwardDraft={department:"Kitchen",store:"Downtown Kitchen",date:"2026-09-14",issuedTo:"",reference:"",remarks:"",items:[]};showView("outward")}
function cancelOutward(){outwardDraft={department:"Kitchen",store:"Downtown Kitchen",date:"2026-09-14",issuedTo:"",reference:"",remarks:"",items:[]};showView("outward")}
function deleteOutward(){if(!canManage()){toast("Only Owner or Admin can cancel outward vouchers");return}if(!outwardDraft.no||!confirm(`Cancel ${outwardDraft.no}?`))return;const no=outwardDraft.no;state.transactions=state.transactions.filter(t=>t.ref!==no);state.outwards=state.outwards.filter(v=>v.no!==no);rebuildStock();toast(`${no} cancelled`);cancelOutward()}
function printVoucherDocument(kind,voucher){const settings=state.settings.general||{},isPurchase=kind==="Purchase",title=isPurchase?"PURCHASE BILL":"STOCK OUTWARD",items=voucher.items||[],total=Number(voucher.total||items.reduce((a,i)=>a+Number(i.amount||0),0)),rows=items.map((i,n)=>`<tr><td>${n+1}</td><td>${i.product||""}</td><td>${productByName(i.product)?.brand||"—"}</td><td>${numberValue(i.qty)}</td><td>${i.unit||productByName(i.product)?.unit||"—"}</td><td class="num">${numberValue(i.rate||i.cost||0)}</td><td class="num">${numberValue(i.amount||Math.abs(i.qty)*(i.rate||i.cost||0))}</td></tr>`).join(""),extra=isPurchase?`<span><b>Supplier:</b> ${voucher.supplier||"—"}</span><span><b>Store:</b> ${voucher.store||"—"}</span>`:`<span><b>Department:</b> ${voucher.department||"—"}</span><span><b>Store:</b> ${voucher.store||"—"}</span><span><b>Issued to:</b> ${voucher.issuedTo||"—"}</span>`;const html=`<!doctype html><html><head><title>${title} ${voucher.no}</title><style>body{font:13px Arial,sans-serif;color:#17253d;margin:0;background:#eef2f6}.sheet{max-width:900px;margin:25px auto;background:#fff;padding:38px;box-shadow:0 4px 18px #17253d22}header{display:flex;justify-content:space-between;border-bottom:3px solid #2864e8;padding-bottom:18px}h1{margin:0;font-size:25px;color:#2864e8}h2{margin:5px 0 0;font-size:16px}p{color:#718099;margin:5px 0}.meta{display:flex;gap:22px;flex-wrap:wrap;background:#f6f8fb;padding:14px;margin:20px 0}.meta span{min-width:170px}table{width:100%;border-collapse:collapse;margin-top:12px}th{background:#17253d;color:#fff;text-align:left;padding:10px;font-size:11px}td{padding:11px 10px;border-bottom:1px solid #e7ebf1}.num{text-align:right}.total{display:flex;justify-content:flex-end;margin-top:18px;font-size:18px;font-weight:bold}.notes{margin-top:28px;border-top:1px solid #e7ebf1;padding-top:14px;color:#718099}.sign{display:flex;justify-content:space-between;margin-top:55px;color:#718099}@media print{body{background:#fff}.sheet{margin:0;box-shadow:none;padding:10px}}</style></head><body><main class="sheet"><header><div><h1>StockSense</h1><h2>${settings.company||"Inventory Management"}</h2><p>${settings.address||""} ${settings.phone||""}</p></div><div style="text-align:right"><h1>${title}</h1><h2>${voucher.no||"DRAFT"}</h2><p>${fmtDate(voucher.date||new Date().toISOString())}</p></div></header><div class="meta"><span><b>Entry No:</b> ${voucher.no||"Draft"}</span><span><b>Date:</b> ${fmtDate(voucher.date||new Date().toISOString())}</span>${extra}<span><b>User:</b> ${voucher.user||state.currentUser}</span></div><table><thead><tr><th>#</th><th>Item Name</th><th>Brand</th><th>Quantity</th><th>Unit</th><th class="num">Rate</th><th class="num">Amount</th></tr></thead><tbody>${rows}</tbody></table><div class="total">Total: ${numberValue(total)}</div><div class="notes"><b>Narration / Remarks:</b> ${voucher.remarks||"—"}${voucher.reference?`<br><b>Reference:</b> ${voucher.reference}`:""}</div><div class="sign"><span>Prepared by: ${voucher.user||state.currentUser}</span><span>Authorized signature</span></div></main><script>window.onload=()=>window.print()<\/script></body></html>`;const win=window.open("","_blank","width=1000,height=800");if(!win){toast("Allow pop-ups to preview the PDF bill");return}win.document.write(html);win.document.close()}
function printPurchase(no){const v=state.purchases.find(x=>x.no===no)||purchaseDraft;if(!v?.items?.length){toast("Save the purchase before opening its PDF preview");return}printVoucherDocument("Purchase",v)}
