let reportFilterState={range:"This Month",from:`${today.slice(0,8)}01`,to:today,department:"",item:"",category:"",supplier:"",store:"",type:"",user:"",number:"",status:"",stockStatus:"",search:"",minQty:"",maxQty:"",minRate:"",maxRate:"",minAmount:"",maxAmount:"",action:""};
