function reportDateRange(range,from,to){const end=new Date(today+"T23:59:59"),start=new Date(end);if(range==="Today")start.setHours(0,0,0,0);else if(range==="Yesterday"){start.setDate(start.getDate()-1);start.setHours(0,0,0,0);end.setDate(end.getDate()-1);end.setHours(23,59,59,999)}else if(range==="This Week"){start.setDate(start.getDate()-start.getDay());start.setHours(0,0,0,0)}else if(range==="This Month"){start.setDate(1);start.setHours(0,0,0,0)}else if(range==="Previous Month"){start.setMonth(start.getMonth()-1,1);start.setHours(0,0,0,0);end.setDate(0);end.setHours(23,59,59,999)}else if(range==="Current Financial Year"){start.setFullYear(start.getFullYear(),3,1);start.setHours(0,0,0,0)}else if(range==="Previous Financial Year"){start.setFullYear(start.getFullYear()-1,3,1);start.setHours(0,0,0,0);end.setFullYear(end.getFullYear(),2,31);end.setHours(23,59,59,999)}else if(range==="Custom"){return [new Date((from||`${today.slice(0,8)}01`)+"T00:00:00"),new Date((to||today)+"T23:59:59")]}return [start,end]}
function multiSelect(id,label,values){const selected=(reportFilterState[id==="report-department"?"department":"item"]||"").split("|");return `<label class="report-filter-field">${label}<select id="${id}" multiple size="1" onchange="applyReportFilters()">${values.map(v=>`<option value="${v}" ${selected.includes(v)?"selected":""}>${v}</option>`).join("")}</select></label>`}
