function reportResultTable(rows){const purchase=rows.filter(t=>t.type==="Purchase").reduce((a,t)=>a+Math.abs(t.qty)*t.cost,0),outward=rows.filter(t=>t.type==="Stock Outward").reduce((a,t)=>a+Math.abs(t.qty)*t.cost,0),quantity=rows.reduce((a,t)=>a+Math.abs(t.qty),0);return `<div class="report-result-summary"><b>Showing ${rows.length} matching records</b><span>Total quantity ${numberValue(quantity)}</span><span>Purchase ${numberValue(purchase)}</span><span>Outward ${numberValue(outward)}</span></div><div class="panel view-table"><div class="panel-head"><span class="panel-title">Filtered report data</span><span class="pill">${rows.length} records</span></div><table class="table"><thead><tr><th>Date</th><th>Entry no.</th><th>Type</th><th>Item</th><th>Department</th><th>Warehouse</th><th>Quantity</th><th>Rate</th><th>Amount</th><th>User</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${fmtDate(t.date)}</td><td><b>${t.ref}</b></td><td><span class="tag">${t.type}</span></td><td>${t.product}</td><td>${t.department||"—"}</td><td>${t.store||"—"}</td><td>${numberValue(Math.abs(t.qty))}</td><td>${numberValue(t.cost)}</td><td>${numberValue(Math.abs(t.qty)*t.cost)}</td><td>${t.user||"—"}</td></tr>`).join("")||'<tr><td colspan="10" class="empty-state">No records match the active filters.</td></tr>'}</tbody></table></div>`}
