function universalReports(){const groups=[["Stock",["Current Stock","Stock Ledger","Low Stock"]],["Purchases",["Purchase Register","Purchase Orders","Pending POs","Overdue POs","Partially Received POs","PO vs Actual Purchase","Purchase Analysis"]],["Outward",["Outward Register","Outward Analysis"]],["Analysis",["Department Summary","Item Movement","Purchase vs Outward"]],["Audit",["Transaction History","User Activity","Backdated Transactions"]]];return layout("Reports","Filter stock, purchasing, outward, analysis and audit data from one live ledger.",`<button class="secondary" onclick="exportFilteredReport()">Export filtered CSV</button><button class="secondary" onclick="window.print()">Print</button>`,`<div class="report-dashboard"><div class="report-categories"><h3>Report centre</h3>${groups.map(g=>`<div class="report-group"><b>${g[0]}</b>${g[1].map(x=>`<button onclick="${reportAction(x)}">${x}<span>›</span></button>`).join("")}</div>`).join("")}</div><div class="report-main">${reportFilters()}<div id="report-results">${reportResultTable(state.transactions)}</div></div></div>`)}
function exportFilteredReport(){reportRowsCache=filteredReportRows();const rows=reportRowsCache.map(t=>[t.date,t.ref,t.type,t.product,t.department||"",t.store||"",Math.abs(t.qty),t.cost,Math.abs(t.qty)*t.cost,t.user||""]);const csv=[["Report","StockSense filtered report"],["Date range",reportFilterState.range],["Department",reportFilterState.department||"All"],[],["Date","Entry No","Type","Item","Department","Warehouse","Quantity","Rate","Amount","User"],...rows].map(r=>r.map(v=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="stocksense-filtered-report.csv";a.click();toast(`${rows.length} filtered records exported`)}
document.addEventListener("keydown",e=>{if(!document.querySelector(".universal-report-filter"))return;if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==="f"){e.preventDefault();document.getElementById("report-search")?.focus()}if(e.ctrlKey&&e.key==="Enter"){e.preventDefault();applyReportFilters()}if(e.ctrlKey&&e.shiftKey&&e.key.toLowerCase()==="x"){e.preventDefault();exportFilteredReport()}});
