function deleteStore(i){if(!canManage()){toast("Only Owner or Admin can delete stores");return}const s=state.stores[i];if(!s||!confirm(`Delete ${s[0]}? Existing ledger history will remain.`))return;if(state.products.some(p=>p.store===s[0])){toast("Move or reassign items from this store before deleting");return}state.stores.splice(i,1);save();showView("stores");toast("Store deleted")}
function toggleUser(i){if(!state.users[i]||state.users[i].role==="Owner"){toast("The Owner user cannot be disabled");return}state.users[i].active=!state.users[i].active;save();showView("users")}
function showView(view){const focus=captureEntryFocus();document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===view));document.getElementById("page-title").textContent=titleCase(view);if(view==="settings"){document.getElementById("app-content").innerHTML=settingsScreen();return}if(view==="stores"){document.getElementById("app-content").innerHTML=storesScreen();return}if(view==="users"){document.getElementById("app-content").innerHTML=usersScreen();return}if(view==="purchase-orders"){document.getElementById("app-content").innerHTML=purchaseOrdersScreen();if(focus)setTimeout(()=>restoreEntryFocus(focus),0);return}let html;if(view==="dashboard")html=dashboard();else if(view==="outward")html=outwardDraft.isNew||outwardDraft.no?outwardScreen():outwardHistory();else if(view==="inventory")html=inventory();else if(view==="inventory-ledger")html=layout("Stock ledger","Every stock movement with date, product, store, cost, reference and user.",`<button class="secondary" onclick="toast('Ledger export prepared')">⇩ Export ledger</button>`,`<div class="view-table"><div class="panel"><div class="panel-head"><span class="panel-title">Transaction history</span><span class="pill">${state.transactions.length} transactions</span></div>${ledgerRows(state.transactions)}</div></div>`);else if(view==="products")html=genericTable("Products","Item master, brands, units, thresholds and average cost.",`<button class="primary" onclick="openModal('product')">＋ Add item</button>`,["Item name","Brand","Category","Unit","Min / Reorder / Max","Purchase rate","Status"],state.products.map(p=>[`<div class="product-cell"><span class="product-dot">${p.icon}</span>${p.name}</div>`,p.brand||"—",p.category,p.unit,`${p.min} / ${p.reorder} / ${p.max}`,money(p.purchaseCost),'<span class="status ok">Active</span>']));else if(view==="purchasing")html=purchaseDraft.isNew||purchaseDraft.no?purchaseScreen():purchaseHistory();else if(view==="stores")html=genericTable("Stores & transfers","Locations, transfer requests, approvals, dispatch and receiving.",`<button class="primary" onclick="openModal('transfer')">＋ Transfer stock</button>`,["Location / reference","Type","From","To","Quantity","Status"],[...state.stores.map(s=>[s[0],"Store stock","—","—",s[3]+" products",'<span class="status ok">Active</span>']),["TRF-00028","Transfer","Riverside Store","Downtown Kitchen","10 kg",'<span class="status ok">Received</span>']]);else if(view==="suppliers")html=genericTable("Suppliers","Supplier contacts, lead time, outstanding balance and purchase history.",`<button class="primary" onclick="openModal('supplier')">＋ Add supplier</button>`,["Supplier","Category","Contact","Lead time","Outstanding","Status"],state.suppliers.map(s=>[s[0],s[1],s[2],s[3]+" days",money(s[4]),'<span class="status ok">Active</span>']));else if(view==="reports")html=universalReports();else if(view==="users")html=genericTable("Users & security","Roles, permissions, access locations and account activity.",`<button class="primary" onclick="openModal('user')">＋ Invite user</button>`,["User","Role","Location","Permissions","Last active","Status"],[["Alex Kim","Owner","All locations","Full access","Just now",'<span class="status ok">Active</span>'],["Maya Chen","Store manager","Downtown Kitchen","Inventory + purchasing","12 min ago",'<span class="status ok">Active</span>'],["Sam Rivera","Inventory clerk","Riverside Store","Stock control","2 hrs ago",'<span class="status ok">Active</span>']]);else if(view==="audit")html=layout("Activity & audit log","Immutable history of stock changes and administrative actions.",`<button class="secondary" onclick="toast('Audit export prepared')">⇩ Export log</button>`,`<div class="view-table"><div class="panel"><div class="panel-head"><span class="panel-title">Audit history</span><span class="pill">All activity</span></div>${ledgerRows(state.transactions)}</div></div>`);else if(view==="settings")html=layout("Settings","Configure business, stores, units, tax, notifications and data protection.",`<button class="primary" onclick="toast('Settings saved')">Save changes</button>`,`<div class="grid-2">${["Business profile","Stores & locations","Units & conversion","Tax configuration","Notifications","Backup & restore","System configuration"].map((x,i)=>`<div class="panel"><div class="panel-head"><span class="panel-title">${x}</span><span class="tag">${i<2?"Configured":"Manage"}</span></div><p class="subtitle">Manage ${x.toLowerCase()} for StockSense.</p><button class="secondary" onclick="toast('${x} opened')">Configure →</button></div>`).join("")}</div>`);else html=dashboard();document.getElementById("app-content").innerHTML=html;if(view==="reports")setTimeout(applyReportFilters,0);if(focus)setTimeout(()=>restoreEntryFocus(focus),0)}
function filterRows(id,inputId){const root=document.getElementById(id),bar=root?.previousElementSibling?.classList.contains("filterbar")?root.previousElementSibling:root?.previousElementSibling?.previousElementSibling,input=document.getElementById(inputId)||bar?.querySelector("input"),q=(input?.value||"").toLowerCase();root?.querySelectorAll("tbody tr").forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?"":"none")}
function fieldHtml(f){if(f==="product")return `<select id="f-product">${state.products.map(p=>`<option>${p.name}</option>`).join("")}</select>`;if(f==="supplier")return `<select id="f-supplier">${state.suppliers.map(s=>`<option>${s[0]}</option>`).join("")}</select>`;if(f==="category")return `<select id="f-category"><option>Dairy</option><option>Vegetables</option><option>Pantry</option><option>Beverages</option></select>`;if(f==="role")return `<select id="f-role"><option>Store manager</option><option>Inventory clerk</option><option>Auditor</option></select>`;if(f==="brand")return `<input id="f-brand" type="text" placeholder="Enter brand...">`;return `<input id="f-${f}" type="${f==="quantity"?"number":"text"}" placeholder="${f==="quantity"?"0.00":"Enter "+f+"..."}">`}
function openModal(type,index){const existing=type==="store"?state.stores[index]:type==="user"?state.users[index]:null;const configs={adjust:["Stock adjustment","Post a signed adjustment to the ledger.",["product","quantity","reason"]],purchase:["Goods received","Receive goods and create Stock In transactions.",["product","quantity","supplier"]],wastage:["Record wastage","Create a Stock Out transaction for damaged or expired goods.",["product","quantity","reason"]],transfer:["Stock transfer","Create paired Stock Out and Stock In ledger entries.",["product","quantity","destination"]],count:["Stock count","Record a variance adjustment from a physical count.",["product","quantity","reason"]],product:["Add product","Create an item master record. Stock remains zero until an inventory transaction is posted.",["name","brand","category"]],supplier:["Add supplier","Create a supplier record with lead time.",["name","supplier"]],store:[index===undefined?"Create store":"Edit store","Manage a warehouse or inventory location.",["storeName","description","manager"]],user:[index===undefined?"Create user":"Edit user","Manage a StockSense user and active session identity.",["name","role","location"]]};const c=configs[type]||configs.adjust;const fields=c[2].map(f=>`<div class="form-field"><label>${titleCase(f)}</label><input id="f-${f}" value="${existing?(type==="store"?existing[{"storeName":0,"description":1,"manager":2}[f]]:existing[f]||""):""}" placeholder="Enter ${titleCase(f).toLowerCase()}"></div>`).join("");document.getElementById("modal-root").innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><h2>${c[0]}</h2><p>${c[1]}</p><div class="form-grid">${fields}</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="submitModal('${type}',${index===undefined?"undefined":index})">${type==="product"?"Save item":type==="store"||type==="user"?"Save changes":"Post to ledger"}</button></div></div></div>`}
function closeModal(){document.getElementById("modal-root").innerHTML=""}
function submitModal(type,index){const p=productByName(document.getElementById("f-product")?.value),qty=Number(document.getElementById("f-quantity")?.value||0);if(type==="store"){const name=document.getElementById("f-storeName").value.trim();if(!name){toast("Store name is required");return}const value=[name,document.getElementById("f-description").value.trim(),document.getElementById("f-manager").value.trim(),index===undefined?0:state.stores[index][3]];if(index===undefined)state.stores.push(value);else state.stores[index]=value;save();closeModal();showView("stores");toast(index===undefined?"Store created":"Store updated");return}if(type==="user"){const name=document.getElementById("f-name").value.trim(),role=document.getElementById("f-role").value.trim(),location=document.getElementById("f-location").value.trim();if(!name||!role){toast("User name and role are required");return}const value={name,role,location:location||"All locations",active:true};if(index===undefined)state.users.push(value);else state.users[index]={...state.users[index],...value};save();closeModal();showView("users");toast(index===undefined?"User created":"User updated");return}if(["adjust","purchase","wastage","transfer","count"].includes(type)){if(!p||!qty){toast("Product and quantity are required");return}const signed=type==="wastage"?-qty:type==="count"?qty-p.stock:type==="adjust"?qty:qty;p.stock+=signed;const kind=type==="wastage"?"Wastage":type==="count"?"Count variance":type==="adjust"?"Adjustment":type==="transfer"?"Transfer out":"Purchase";state.transactions.unshift({id:"TX-"+Date.now(),date:new Date().toISOString(),type:kind,product:p.name,store:p.store,qty:signed,cost:p.cost,user:state.currentUser,ref:(kind==="Purchase"?"GRN-":kind==="Wastage"?"WST-":kind==="Transfer out"?"TRF-":"ADJ-")+Date.now().toString().slice(-5)});if(type==="transfer"){state.transactions.unshift({id:"TX-"+Date.now()+"-in",date:new Date().toISOString(),type:"Transfer in",product:p.name,store:document.getElementById("f-destination")?.value||"Riverside Store",qty:qty,cost:p.cost,user:state.currentUser,ref:"TRF-"+Date.now().toString().slice(-5)})}save();closeModal();toast(`${kind} posted to stock ledger`);showView(document.querySelector(".nav-item.active")?.dataset.view||"dashboard")}else if(type==="product"){const name=document.getElementById("f-name")?.value.trim(),brand=document.getElementById("f-brand")?.value.trim(),category=document.getElementById("f-category")?.value;if(!name||!brand){toast("Item name and brand are required");return}const id=Math.max(0,...state.products.map(x=>Number(x.id)||0))+1;state.products.push({id,name,sku:"",barcode:"",category,brand,department:"Kitchen",unit:"piece",packSize:0,packUnit:"piece",stock:0,min:0,reorder:0,max:0,cost:0,purchaseCost:0,sellingCost:0,active:true,trackDepartment:true,store:"Downtown Kitchen",expiry:"",icon:"▣"});state.openingStock=state.openingStock||{};state.openingStock[name]=0;save();closeModal();showView("inventory");toast("Item added to master; stock remains zero")}else{closeModal();toast("Record saved successfully")}}
document.addEventListener("click",event=>{const button=event.target.closest(".nav-item[data-view]");if(button)showView(button.dataset.view)});
document.getElementById("global-search").addEventListener("keydown",e=>{if(e.key==="Enter"&&e.target.value){showView("inventory");setTimeout(()=>{const i=document.getElementById("inv-search");if(i){i.value=e.target.value;filterRows("inventory-table")}},0)}});
document.addEventListener("keydown",e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();document.getElementById("global-search").focus()}if(e.key==="Escape"){if(document.getElementById("modal-root").innerHTML)closeModal();else if(document.querySelector(".outward-grid"))cancelOutward()}if(document.querySelector(".outward-grid")){if(e.key==="F2"){e.preventDefault();document.getElementById("out-date")?.focus()}if(e.key==="F3"){e.preventDefault();document.getElementById("out-department")?.focus()}if(e.key==="F4"){e.preventDefault();document.getElementById("out-store")?.focus()}if(e.key==="F5"||(e.ctrlKey&&e.key.toLowerCase()==="a")){e.preventDefault();addOutwardRow()}if(e.key==="F6"){e.preventDefault();document.querySelector(".out-qty:last-of-type")?.focus()}if(e.key==="F7"||(e.ctrlKey&&e.key.toLowerCase()==="d")){e.preventDefault();removeOutwardRow(Math.max(outwardDraft.items.length-1,0))}if(e.key==="F8"||(e.ctrlKey&&e.key.toLowerCase()==="s")){e.preventDefault();saveOutward()}if(e.key==="F9"){e.preventDefault();printOutward()}if(e.altKey&&e.key.toLowerCase()==="s"){e.preventDefault();document.querySelector(".out-item:last-of-type")?.focus()}}});
showView("dashboard");
